"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9910],{67458:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"ClientReadyController","desc":"Announces this client\'s readiness to receive join-time snapshots, exactly\\nonce, by firing `Packets.ClientReady`.\\n\\nTiming matters. The vendored `Packet` library dispatches incoming payloads\\ninto signals with no backlog, so a snapshot that arrives before a consuming\\nscript has connected its handler is dropped. Waiting for `game.Loaded` and\\nthen deferring gives every `StarterPlayerScript` the chance to run its\\ntop-level code and connect. This is a best-effort gate, not a proof \u2014\\n`TrainStateCache` is what makes a late subscriber recoverable, and the two\\nmechanisms are intended to be used together.","realm":["Client"],"source":{"line":18,"path":"src/StarterPlayer/StarterPlayerScripts/ClientReadyController.client.luau"}}')}}]);